DROP TABLE IF EXISTS _example_images;

CREATE TABLE _example_images(
    item_id TEXT PRIMARY KEY,
    image_data TEXT NOT NULL
);

ALTER TABLE _example_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY restrict_owner ON _example_images FOR ALL TO postgres;

